contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount);

        bool reverted;
        uint256 balBefore = address(c).balance;

        c.withdraw{value: sendAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = address(c).balance;

        assert(reverted || (balAfter == 0 && balBefore + sendAmount > balAfter));
    }

    receive() external payable {}
}

