// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        bool reverted;
        uint256 balBefore = address(c).balance;
        try c.withdraw{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter = address(c).balance;
        assertTrue(reverted || (balAfter == 0 && balBefore + sendAmount > balAfter));
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable {}
}
